/* @lc app=leetcode id=3357 lang=kotlin */ class Solution { fun minDifference(nums: IntArray): Int = nums.size.let { n -> (1 until n).filter { nums[it] != -1 && nums[it - 1] != -1 }.maxOfOrNull { Math.abs(nums[it] - nums[it - 1]) }.let { it ?: 0 }.let { base -> nums.indices.filter { nums[it] == -1 && (it == 0 || nums[it - 1] != -1) }.map { i -> generateSequence(i) { it + 1 }.takeWhile { it < n && nums[it] == -1 }.count().let { len -> Triple(if (i > 0) nums[i - 1] else null, if (i + len < n) nums[i + len] else null, len) } }.let { runs -> runs.flatMap { listOfNotNull(it.first, it.second) }.let { nb -> if (nb.isEmpty()) base else maxOf(base, generateSequence(0L to 1_000_000_000L) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { D -> (nb.min() + D).let { x -> maxOf(1L, nb.max() - D).let { y -> if (runs.all { (l, r, len) -> listOf(x, y).let { vs -> if (l != null && r != null) vs.any { v1 -> Math.abs(l - v1) <= D && vs.any { v2 -> Math.abs(r - v2) <= D && (if (len == 1) v1 == v2 else v1 == v2 || Math.abs(x - y) <= D) } } else vs.any { v -> Math.abs((l ?: r!!) - v) <= D } } }) lo to D else D + 1 to hi } } } }.last().first.toInt()) } } } } }